mapper.sql:
WHERE 1 = 1 
AND COALESCE(t.update_time, t.create_time) >= #{start}
AND (COALESCE(t.update_time, t.create_time) < #{end}
     OR COALESCE(t.update_time, t.create_time) IS NULL)

mapper.select:
SELECT DATE_FORMAT(COALESCE(t.update_time, t.create_time), '%Y-%m-%d') AS date, COUNT(*) AS value
FROM video_tags t WHERE COALESCE(t.update_time, t.create_time) >= #{calendarStart}
  AND COALESCE(t.update_time, t.create_time) < #{end} 
GROUP BY date ORDER BY date

mapper.sql:
WHERE v.latest = 1 AND v.first_time IS NOT NULL AND v.first_time < #{end}
AND v.first_time >= #{start}
GROUP BY date ORDER BY date
